import{z as s,x as B,o as l,c as A,q as p,j as i,D as e,d as t,s as o,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"PEER 百万专家","description":"","frontmatter":{"title":"PEER 百万专家","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/peer-million-experts.md","filePath":"llm/peer-million-experts.md","lastUpdated":1791063341000}'),m={name:"llm/peer-million-experts.md"};function d(u,E,f,h,x,D){const r=B("Mermaid");return l(),A("div",null,[E[2]||(E[2]=p('<h1 id="peer-百万专家" tabindex="-1">PEER 百万专家 <a class="header-anchor" href="#peer-百万专家" aria-label="Permalink to &quot;PEER 百万专家&quot;">​</a></h1><div class="epigraph"><p>专家数可以到百万，每个专家极小；路由变成从嵌入表里检索若干近邻，而不是对 $N$ 维 softmax。</p><footer>—— He, Mixture of A Million Experts, 2024</footer></div><p><a href="/llm/expert-pruning-merging">上一课</a>在几十到几百专家上做减法。PEER（Parameter Efficient Expert Retrieval）走加法：\\(N\\) 极大、单专家极窄，门不再对全部专家打 logits——那是 \\(\\Theta(N)\\) 的不可行。本课补检索式路由：query 向量在专家嵌入表上做近邻，只激活取出的几个。后课层次 MoE 用树降低检索难度；本课先给平坦百万表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/switch-transformer">Switch</a> 的门是 \\(d\\times N\\) 矩阵，\\(N=10^6\\) 时门比专家还大，且 softmax 不可用。<a href="/llm/hash-routing">哈希路由</a> 能分派但无内容近邻。缺口是 <strong>sublinear 检索</strong>：专家各有一个短嵌入，token 用 \\(q=Wx\\) 去表里找 top-\\(k\\) 近邻，只加载那些极小 MLP。均衡靠嵌入空间的覆盖，而不是 \\(N\\) 维辅助损失。</p><p><span class="marginnote">直觉类比：softmax 门像把一百万本书的书名从头念一遍再挑（每层都要付一遍）；检索式路由像先查卡片盒（专家嵌入表），直接走向相似主题的那几个书架。两者回答的都是「哪些专家该干活」，代价却从一百万次比较降到近似对数次。</span></p><p>He 的 PEER 把专家做成单神经元或极窄层，用乘积量化一类结构让检索可扩展。课序抓住「路由即检索」，不把量化索引展开成向量数据库课。</p><p><span class="marginnote">这不是序列召回瓶颈那一课的 KV 检索。专家表是模型参数，跨序列共享；KV 是当前上下文。二者都叫检索，对象不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每个专家 \\(i\\) 存 \\(e_i\\in\\mathbb{R}^{d_e}\\) 与极小权重。路由：\\(q=W_q x\\)，取 \\(\\mathrm{top}k_i\\,\\langle q,e_i\\rangle\\)，输出 \\(\\sum_{i\\in\\mathcal{K}} \\pi_i E_i(x)\\)。\\(\\pi\\) 可由内积 softmax 在 \\(k\\) 内归一。训练要对取出的 \\(e_i\\) 与 \\(W_q\\) 做梯度；对未取出的专家无梯度——百万里绝大多数永不更新的风险，要用随机负样本或周期性探索，否则表塌成少数热点嵌入。</p><p>实现上专家表分片到各机，近邻搜索用 IVF / PQ 近似。近似邻居与精确 top-\\(k\\) 的不一致是训练噪声，类似MoE 的 drop。</p><p><span class="marginnote">常见误区：把专家嵌入表的检索想成「模型在查外部知识库」。表是模型自己的参数，随训练一起更新；它检索的不是文档，而是「该由哪个小 MLP 处理这个 token」。这与 RAG 的向量库（存外部文本、参数不动）完全是两回事。</span></p><h3 id="与普通-top-门" tabindex="-1">与普通 top-\\(k\\) 门 <a class="header-anchor" href="#与普通-top-门" aria-label="Permalink to &quot;与普通 top-$k$ 门&quot;">​</a></h3><p>普通门对每个专家一个独立 logit 轴，专家之间只通过 softmax 竞争。PEER 的竞争发生在嵌入空间的几何上：相近 \\(e_i\\) 会被相似 \\(q\\) 一起取出，自然形成专家簇。上一课的「相关簇」在这里是空间上的球，合并变成合并近邻专家。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>容量来自组合：每次 \\(k\\) 个极小专家，组合数 \\(\\binom{N}{k}\\) 巨大，表达力可以很大，单次 FLOPs 仍小。这是稀疏 MoE 故事推到极限。代价是优化与系统：大多数专家长期零梯度，专精分析几乎无法对单个专家做干预——必须对空间区域做。</p>',16)),(l(),i(n,null,{default:e(()=>[o(r,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E7%83%AD%E9%97%A8%20query%20%E6%96%B9%E5%90%91%E5%8F%8D%E5%A4%8D%E5%87%BA%E7%8E%B0%22%5D%20--%3E%20SEL%5B%22%E5%90%8C%E4%B8%80%E6%89%B9%E8%BF%91%E9%82%BB%E4%B8%93%E5%AE%B6%E8%A2%AB%E5%8F%8D%E5%A4%8D%E5%8F%96%E5%87%BA%22%5D%0A%20%20SEL%20--%3E%20G%5B%22%E5%85%B6%E4%BD%99%E7%99%BE%E4%B8%87%E4%B8%93%E5%AE%B6%E9%95%BF%E6%9C%9F%E9%9B%B6%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20G%20--%3E%20W%5B%22%E8%A2%AB%E5%8F%96%E5%87%BA%E8%80%85%E6%9B%B4%E5%8A%A0%E4%B8%93%E7%B2%BE%E8%AF%A5%E6%96%B9%E5%90%91%22%5D%0A%20%20W%20--%3E%20HOT%5B%22%E4%B8%8B%E4%B8%80%E8%BD%AE%E6%9B%B4%E7%83%AD%EF%BC%8C%E5%BE%AA%E7%8E%AF%E8%87%AA%E6%88%91%E5%8A%A0%E5%BC%BA%22%5D%0A%20%20HOT%20--%3E%20COL%5B%22%E6%95%B4%E5%BC%A0%E8%A1%A8%E5%A1%8C%E6%88%90%E5%B0%91%E6%95%B0%E7%83%AD%E7%82%B9%E7%B0%87%22%5D%0A%20%20EXP%5B%22%E9%9A%8F%E6%9C%BA%E8%B4%9F%E6%A0%B7%E6%9C%AC%20%2F%20%E5%91%A8%E6%9C%9F%E6%80%A7%E6%8E%A2%E7%B4%A2%22%5D%20--%3E%20BRK%5B%22%E6%96%B0%E4%B8%93%E5%AE%B6%E8%8E%B7%E5%BE%97%E6%A2%AF%E5%BA%A6%EF%BC%8C%E8%A6%86%E7%9B%96%E4%B8%8D%E8%A2%AB%E6%8A%BD%E7%A9%BA%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"数字实例：取 \\(N=10^6\\)、\\(k=4\\)。可选专家组合约 \\(\\binom{10^6}{4}\\approx 4\\times 10^{22}\\)——单步只付 4 个极小专家的 FLOPs，表达力却摊在天文数字的组合里。反面是：每个专家被抽中的先验只有 \\(k/N=0.0004\\%\\)，不刻意探索就几乎注定永不更新。")],-1)),E[4]||(E[4]=a("p",null,"负载均衡：热点 query 方向会打热球。无辅助损失偏置可加在取出的内积上，或对过热嵌入做范数惩罚。哈希可做粗分桶再精确检索，等价于层次化的第一层，下一课正式写树。百万表的初始化不能随机到互为正交：随机高维近邻没有语义团，早期路由等于噪声哈希，叶子吃不到连贯数据。嵌入常从词向量或上一层表示蒸馏冷启动。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"微调 PEER 时 LoRA 打在 \\(W_q\\) 会整体重绘检索；打在单个专家几乎无意义。应 LoRA 查询投影加少量热专家。")],-1)),E[6]||(E[6]=a("h2",{id:"边界",tabindex:"-1"},[t("边界 "),a("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),E[7]||(E[7]=a("p",null,"近似近邻使训推一致性变难。单专家过窄，数值与通信启动开销可能压过 GEMM。不要在尚未解决几十专家负载的代码库上「先上百万」。粒度律课会问极窄专家是否总是更优；PEER 是该问题的极端点，不是自动最优。层次 MoE 用显式树替代平坦 PQ，往往更可控。",-1)),(l(),i(n,null,{default:e(()=>[o(r,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22token%22%5D%20--%3E%20Q%5B%22%E6%9F%A5%E8%AF%A2%20q%22%5D%0A%20%20Q%20--%3E%20ANN%5B%22%E4%B8%93%E5%AE%B6%E5%B5%8C%E5%85%A5%E8%A1%A8%E8%BF%91%E9%82%BB%22%5D%0A%20%20ANN%20--%3E%20Tiny%5B%22k%20%E4%B8%AA%E6%9E%81%E5%B0%8F%E4%B8%93%E5%AE%B6%22%5D%0A%20%20Tiny%20--%3E%20Y%5B%22%E5%8A%A0%E6%9D%83%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[8]||(E[8]=a("h2",{id:"小结",tabindex:"-1"},[t("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),E[9]||(E[9]=a("ul",null,[a("li",null,"PEER 用检索代替 \\(N\\) 维 softmax，使百万极小专家可行。"),a("li",null,"未取出专家无梯度，必须探索或负采样，否则表塌缩。"),a("li",null,"专精单位是嵌入空间中的区域，不是单个专家名。"),a("li",null,"系统与近似邻居一致性是主风险；不是默认部署形态。"),a("li",null,"出处：He, 2024。")],-1))])}const F=s(m,[["render",d]]);export{k as __pageData,F as default};
